package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.json.*;

/** Durable backup phases. Only an explicit preview confirmation can replace the library. */
final class BackupWork {
    static void enqueue(Activity a,Uri uri,boolean restore,boolean conversations,boolean audio){enqueue(a,uri,restore,conversations,audio,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}
    static void enqueue(Activity a,Uri uri,boolean restore,boolean conversations,boolean audio,int flags){int granted=flags&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);for(int mode:new int[]{granted,Intent.FLAG_GRANT_READ_URI_PERMISSION,Intent.FLAG_GRANT_WRITE_URI_PERMISSION})if((granted&mode)==mode&&mode!=0)try{a.getContentResolver().takePersistableUriPermission(uri,mode);}catch(RuntimeException ignored){}
        PlusUi.run(a,()->{String id;try(TaskStore db=new TaskStore(a)){id=db.create(restore?"restore":"backup",restore?"Recuperar biblioteca":"Cópia da biblioteca",new JSONObject().put("uri",uri.toString()).put("conversations",conversations).put("audio",audio));}final String job=id;TaskService.launch(a,job);});}
    static void local(Activity a,File file){PlusUi.run(a,()->{File root=new File(a.getFilesDir(),"workspace-recovery").getCanonicalFile();if(!DiskWalker.inside(root,file.getCanonicalFile())||!file.isFile())throw new IOException("Recuperação indisponível.");String id;try(TaskStore db=new TaskStore(a)){id=db.create("restore","Recuperação local",new JSONObject().put("local",true).put("path",file.getPath()));}final String job=id;TaskService.launch(a,job);});}
    static File directory(Context c,String id){if(!id.matches("[a-f0-9-]{36}"))throw new IllegalArgumentException();File dir=new File(c.getCacheDir(),"backup-work-"+id);dir.mkdirs();return dir;}
    static void run(Context c,StudyStore.Row job,TaskStore db,TaskService.Control control)throws Exception{JSONObject data=new JSONObject(job.s("payload"));if(job.s("type").equals("restore"))restore(c,job,db,data,control);else export(c,job,db,data,control);}
    static void export(Context c,StudyStore.Row job,TaskStore db,JSONObject data,TaskService.Control control)throws Exception{String id=job.s("id");File dir=directory(c,id),archive=new File(dir,"library.zip");Uri target=Uri.parse(data.getString("uri"));if(!data.optBoolean("ready")||!archive.isFile()){
            File part=new File(dir,"library.part");try(FileOutputStream out=new FileOutputStream(part)){WorkspaceBackup.write(c,out,false,control::cancelled,text->control.progress(text,0,0),new BackupExtras.Options(data.optBoolean("conversations"),data.optBoolean("audio")));out.getFD().sync();}catch(Exception|OutOfMemoryError e){part.delete();throw e;}Files.move(part.toPath(),archive.toPath(),StandardCopyOption.REPLACE_EXISTING);data.put("ready",true);db.payload(id,data);
        }
        control.check();try(InputStream in=new FileInputStream(archive);OutputStream out=c.getContentResolver().openOutputStream(target,"wt")){if(out==null)throw new IOException("Sem acesso ao destino. Escolha outra pasta.");byte[] buffer=new byte[65536];long copied=0;for(int n;(n=in.read(buffer))!=-1;){control.check();out.write(buffer,0,n);copied+=n;control.progress("A guardar ZIP · "+android.text.format.Formatter.formatShortFileSize(c,copied),copied,archive.length());}out.flush();}control.progress("Cópia completa guardada.",1,1);WorkspaceBackup.remove(dir);
    }
    static WorkspaceBackup.Staged stage(Context c,JSONObject data,TaskService.Control control)throws Exception{
        if(data.optBoolean("local")){File file=new File(data.getString("path")).getCanonicalFile(),root=new File(c.getFilesDir(),"workspace-recovery").getCanonicalFile();if(!DiskWalker.inside(root,file))throw new IOException("Recuperação inválida.");return WorkspaceBackup.stage(c,file,true,control::cancelled,text->control.progress(text,0,0));}
        Uri source=Uri.parse(data.getString("uri"));try(ParcelFileDescriptor fd=c.getContentResolver().openFileDescriptor(source,"r")){if(fd==null)throw new IOException("Cópia indisponível.");boolean seekable=false;try{android.system.Os.lseek(fd.getFileDescriptor(),0,android.system.OsConstants.SEEK_CUR);seekable=new File("/proc/self/fd/"+fd.getFd()).canRead();}catch(Exception ignored){}
            if(seekable)return WorkspaceBackup.stage(c,new File("/proc/self/fd/"+fd.getFd()),false,control::cancelled,text->control.progress(text,0,0));
        }
        File compressed=new File(directory(c,control.id),"input.zip");if(!compressed.isFile())try(InputStream in=c.getContentResolver().openInputStream(source)){if(in==null)throw new IOException("Cópia indisponível.");StudyFiles.copy(in,compressed,Math.max(0,compressed.getParentFile().getUsableSpace()-33554432L),control::cancelled);}
        return WorkspaceBackup.stage(c,compressed,false,control::cancelled,text->control.progress(text,0,0));
    }
    static void keep(WorkspaceBackup.Staged staged,JSONObject data)throws Exception{File manifest=new File(staged.directory,"verified-workspace.json");try(FileOutputStream out=new FileOutputStream(manifest)){out.write(staged.manifest.toString().getBytes(StandardCharsets.UTF_8));out.getFD().sync();}data.put("staged",staged.directory.getPath()).put("verified",true);}
    static WorkspaceBackup.Staged reopen(Context c,JSONObject data)throws Exception{File folder=new File(data.getString("staged")).getCanonicalFile();if(!DiskWalker.inside(c.getCacheDir().getCanonicalFile(),folder)||!folder.getName().startsWith("workspace-restore-"))throw new IOException("Preparação inválida.");File file=new File(folder,"verified-workspace.json");if(!file.isFile()||file.length()>16777216)throw new IOException("A preparação foi removida. Volte a escolher a cópia.");String raw=new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);JsonBudget.check(raw,14,250000);JSONObject manifest=new JSONObject(raw);Map<String,File> entries=new LinkedHashMap<>();JSONArray all=manifest.getJSONArray("entries");boolean local=data.optBoolean("local");for(int i=0;i<all.length();i++){JSONObject item=all.getJSONObject(i);File part=local&&item.optString("kind").equals("file")&&!item.optBoolean("snapshot")?WorkspaceBackup.privateFile(c,item.getString("path")):new File(folder,"part-"+i);if(!part.isFile()||part.length()!=item.getLong("bytes")||!StudyFiles.hash(part).equals(item.getString("sha256")))throw new IOException("A preparação mudou. Verifique novamente a cópia.");entries.put(item.getString("entry"),part);}return new WorkspaceBackup.Staged(folder,manifest,entries,local);}
    static void restore(Context c,StudyStore.Row job,TaskStore db,JSONObject data,TaskService.Control control)throws Exception{String id=job.s("id");if(c.getSharedPreferences("reading_tools",0).getString("last_restore_job","").equals(id)){db.update(id,StudyStore.values("workspace",TaskStore.workspace(c)));control.progress("Biblioteca recuperada.",1,1);return;}
        if(!data.optBoolean("verified")){
            WorkspaceBackup.Staged prepared=stage(c,data,control);try{WorkspaceBackup.Info info=WorkspaceBackup.inspect(c,prepared);data.put("preview",info.summary());keep(prepared,data);db.payload(id,data);}catch(Exception e){prepared.close();throw e;}
            db.state(id,"paused",data.getString("preview")+" · Reveja e confirme a recuperação.");control.stopped=true;throw new InterruptedIOException();
        }
        if(!data.optBoolean("approved")){db.state(id,"paused","Reveja a cópia antes de recuperar.");control.stopped=true;throw new InterruptedIOException();}
        WorkspaceBackup.Staged prepared=reopen(c,data);boolean recovered=false;try{
            SpeechEvents.State voice=SpeechEvents.state;if(voice.active)ReadAloudService.control(c,ReadAloudService.STOP,voice.token);c.stopService(new Intent(c,MediaPlaybackService.class));BackgroundAudioService.stop(c);c.stopService(new Intent(c,StudyTimerService.class));NarrationExportService.pauseJob(c);long until=SystemClock.elapsedRealtime()+45000;while(NarrationExportService.running){control.check();if(SystemClock.elapsedRealtime()>until)throw new IOException("Aguarde a narração pausar e retome a recuperação.");Thread.sleep(100);}
            BackupExtras.typed(prepared.manifest.getJSONObject("preferences"),"reading_tools","last_restore_job",id);
            WorkspaceBackup.restore(c,prepared,control::cancelled,text->{if(text.equals("A recuperar biblioteca, cadernos e preferências…"))control.critical=true;control.progress(text,0,0);});recovered=true;
        }finally{control.critical=false;if(recovered)prepared.close();}
        db.update(id,StudyStore.values("workspace",TaskStore.workspace(c)));control.progress("Biblioteca recuperada. Reabra a biblioteca.",1,1);ReadingWidget.update(c);WorkspaceBackup.remove(directory(c,id));
    }
    static void confirm(Activity a,String id){PlusUi.run(a,()->{JSONObject data;try(TaskStore db=new TaskStore(a)){data=db.payload(id);}final JSONObject value=data;if(!value.optBoolean("verified")){TaskService.start(a,id);return;}PlusUi.post(a,()->new UiDialog.Builder(a).setTitle("Recuperar esta biblioteca?").setMessage(value.optString("preview")+"\n\nSubstitui os dados locais e guarda uma recuperação anterior. Os áudios serão pausados.").setPositiveButton("Recuperar",(d,w)->PlusUi.run(a,()->{try(TaskStore db=new TaskStore(a)){value.put("approved",true);db.payload(id,value);}PlusUi.post(a,()->TaskService.start(a,id));})).setNegativeButton("Cancelar",null).show());});}
    private BackupWork(){}
}
